#include "kernel.h"
#include <hls_math.h>

// ---------------------------------------------------------------------------
// Internal precision: use double-width fixed point for intermediate results
// ---------------------------------------------------------------------------
typedef double calc_t;

// ---------------------------------------------------------------------------
// Small complex helpers operating on calc_t pairs
// ---------------------------------------------------------------------------
struct cx_t {
    calc_t re, im;
};

static cx_t cx_add(cx_t a, cx_t b) {
    cx_t r; r.re = a.re + b.re; r.im = a.im + b.im; return r;
}
static cx_t cx_sub(cx_t a, cx_t b) {
    cx_t r; r.re = a.re - b.re; r.im = a.im - b.im; return r;
}
static cx_t cx_mul(cx_t a, cx_t b) {
    cx_t r;
    r.re = a.re*b.re - a.im*b.im;
    r.im = a.re*b.im + a.im*b.re;
    return r;
}
static cx_t cx_conj(cx_t a) {
    cx_t r; r.re = a.re; r.im = -a.im; return r;
}
static calc_t cx_abs(cx_t a) {
    return hls::sqrt(a.re*a.re + a.im*a.im);
}
static calc_t cx_angle(cx_t a) {
    return hls::atan2(a.im, a.re);
}

// ---------------------------------------------------------------------------
// Matrix size
// ---------------------------------------------------------------------------
#define N 10

// ---------------------------------------------------------------------------
// kernel_top
// ---------------------------------------------------------------------------
void kernel_top(
    in0_t  in0[DIM_IN0_0][DIM_IN0_1],
    in1_t  in1,
    out0_t out0[DIM_OUT0_0],
    out1_t out1[DIM_OUT1_0][DIM_OUT1_1],
    out2_t *out2
)
{
#pragma HLS INTERFACE ap_ctrl_hs port=return
#pragma HLS ARRAY_PARTITION variable=in0  complete dim=0
#pragma HLS ARRAY_PARTITION variable=out0 complete dim=0
#pragma HLS ARRAY_PARTITION variable=out1 complete dim=0

    // ------------------------------------------------------------------
    // Copy input A into internal calc_t array
    // ------------------------------------------------------------------
    cx_t A[N][N];
    #pragma HLS ARRAY_PARTITION variable=A complete dim=0

    COPY_A_ROW: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        COPY_A_COL: for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            A[i][j].re = (calc_t)in0[i][j].re;
            A[i][j].im = (calc_t)in0[i][j].im;
        }
    }

    // ------------------------------------------------------------------
    // Initialise V = eye(N)
    // ------------------------------------------------------------------
    cx_t V[N][N];
    #pragma HLS ARRAY_PARTITION variable=V complete dim=0

    INIT_V_ROW: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        INIT_V_COL: for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            V[i][j].re = (i == j) ? (calc_t)1.0 : (calc_t)0.0;
            V[i][j].im = (calc_t)0.0;
        }
    }

    // ------------------------------------------------------------------
    // Jacobi iteration
    // ------------------------------------------------------------------
    int max_iter_val = (int)in1;
    int z = 0;

    JACOBI_LOOP: for (int iter = 0; iter < 512; iter++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=512

        if (iter >= max_iter_val) break;

        // ---- find pivot (p, q) with largest |A[i,j]|, i<j ----------
        calc_t off_diag_max = (calc_t)0.0;
        int p = 0, q = 1;

        PIVOT_I: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            PIVOT_J: for (int j = i + 1; j < N; j++) {
#pragma HLS UNROLL
                calc_t val = cx_abs(A[i][j]);
                if (val > off_diag_max) {
                    off_diag_max = val;
                    p = i;
                    q = j;
                }
            }
        }

        // ---- convergence check -------------------------------------
        if (off_diag_max < (calc_t)1e-8) break;

        z = iter;

        // ---- compute rotation angles --------------------------------
        cx_t a_pp = A[p][p];
        cx_t a_qq = A[q][q];
        cx_t a_pq = A[p][q];

        calc_t denom = a_pp.re - a_qq.re;
        calc_t numer = (calc_t)2.0 * cx_abs(a_pq);
        calc_t theta, phi;

        if (hls::fabs(denom) < (calc_t)1e-15)
            theta = (calc_t)(3.14159265358979323846 / 4.0);
        else
            theta = (calc_t)0.5 * hls::atan(numer / denom);

        phi = -cx_angle(a_pq);

        calc_t cos_t = hls::cos(theta);
        calc_t sin_t = hls::sin(theta);
        calc_t cos_p = hls::cos(phi);
        calc_t sin_p = hls::sin(phi);

        // U[p][q] = sin(theta)*exp(-j*phi) = sin_t*(cos_p - j*sin_p)
        cx_t U_pp; U_pp.re =  cos_t;                        U_pp.im = (calc_t)0.0;
        cx_t U_pq; U_pq.re =  sin_t * cos_p;                U_pq.im = -sin_t * sin_p;
        cx_t U_qp; U_qp.re =  sin_t * cos_p;                U_qp.im =  sin_t * sin_p;
        cx_t U_qq; U_qq.re = -cos_t;                        U_qq.im = (calc_t)0.0;

        // ---- A = U^H * A * U  (only rows/cols p,q change) ----------

        // Temporary copies of rows p and q of A (before update)
        cx_t Ap[N], Aq[N];
        #pragma HLS ARRAY_PARTITION variable=Ap complete dim=1
        #pragma HLS ARRAY_PARTITION variable=Aq complete dim=1

        SAVE_ROWS: for (int k = 0; k < N; k++) {
#pragma HLS UNROLL
            Ap[k] = A[p][k];
            Aq[k] = A[q][k];
        }

        // Right-multiply: A[:,p] and A[:,q] update  (A = A*U on cols p,q)
        // new A[i][p] = A[i][p]*U_pp + A[i][q]*U_qp
        // new A[i][q] = A[i][p]*U_pq + A[i][q]*U_qq
        cx_t col_p_old[N], col_q_old[N];
        #pragma HLS ARRAY_PARTITION variable=col_p_old complete dim=1
        #pragma HLS ARRAY_PARTITION variable=col_q_old complete dim=1

        SAVE_COLS: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            col_p_old[i] = A[i][p];
            col_q_old[i] = A[i][q];
        }

        RIGHT_MUL: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            A[i][p] = cx_add(cx_mul(col_p_old[i], U_pp), cx_mul(col_q_old[i], U_qp));
            A[i][q] = cx_add(cx_mul(col_p_old[i], U_pq), cx_mul(col_q_old[i], U_qq));
        }

        // Left-multiply: A = U^H * A  (conjugate-transpose of U)
        // affects rows p and q
        // new A[p][k] = conj(U_pp)*A[p][k] + conj(U_qp)*A[q][k]
        // new A[q][k] = conj(U_pq)*A[p][k] + conj(U_qq)*A[q][k]
        // Refresh Ap/Aq after the right multiply
        SAVE_ROWS2: for (int k = 0; k < N; k++) {
#pragma HLS UNROLL
            Ap[k] = A[p][k];
            Aq[k] = A[q][k];
        }

        LEFT_MUL: for (int k = 0; k < N; k++) {
#pragma HLS UNROLL
            A[p][k] = cx_add(cx_mul(cx_conj(U_pp), Ap[k]), cx_mul(cx_conj(U_qp), Aq[k]));
            A[q][k] = cx_add(cx_mul(cx_conj(U_pq), Ap[k]), cx_mul(cx_conj(U_qq), Aq[k]));
        }

        // Enforce exact zeros at pivot
        A[p][q].re = (calc_t)0.0; A[p][q].im = (calc_t)0.0;
        A[q][p].re = (calc_t)0.0; A[q][p].im = (calc_t)0.0;

        // ---- V = V * U  (update eigenvector matrix) ----------------
        cx_t Vp[N], Vq[N];
        #pragma HLS ARRAY_PARTITION variable=Vp complete dim=1
        #pragma HLS ARRAY_PARTITION variable=Vq complete dim=1

        SAVE_VCOLS: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            Vp[i] = V[i][p];
            Vq[i] = V[i][q];
        }

        UPDATE_V: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
            V[i][p] = cx_add(cx_mul(Vp[i], U_pp), cx_mul(Vq[i], U_qp));
            V[i][q] = cx_add(cx_mul(Vp[i], U_pq), cx_mul(Vq[i], U_qq));
        }
    }

    // ------------------------------------------------------------------
    // Write eigenvalues (diagonal of A)
    // ------------------------------------------------------------------
    WRITE_EVALS: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        out0[i].re = (out0_scalar_t)A[i][i].re;
        out0[i].im = (out0_scalar_t)A[i][i].im;
    }

    // ------------------------------------------------------------------
    // Write eigenvectors
    // ------------------------------------------------------------------
    WRITE_EVEC_ROW: for (int i = 0; i < N; i++) {
#pragma HLS UNROLL
        WRITE_EVEC_COL: for (int j = 0; j < N; j++) {
#pragma HLS UNROLL
            out1[i][j].re = (out1_scalar_t)V[i][j].re;
            out1[i][j].im = (out1_scalar_t)V[i][j].im;
        }
    }

    // ------------------------------------------------------------------
    // Write iteration count
    // ------------------------------------------------------------------
    *out2 = (out2_t)z;
}
